/* Design review only: no database/client/model imports; no fetch, IPC or credential storage. */
(() => {
'use strict';
const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = (name,size=15) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${window.catioProtoIcons[name] || window.catioProtoIcons.circle}</svg>`;
const button = (text, action, name='', style='', disabled=false) => `<button class="p-button ${style}" data-act="${action}" ${disabled?'disabled':''}>${name?icon(name):''}${text}</button>`;
const viewButton=(text,view,name='')=>`<button class="p-button" data-view="${view}">${name?icon(name):''}${text}</button>`;
const defaultSql = `-- 设计示例，原型不会执行此 SQL\nSELECT o.id, u.name, o.amount, o.payload\nFROM public.orders AS o\nLEFT JOIN public.users AS u\n  ON o.tenant_id = u.tenant_id\n AND o.user_id = u.id\nWHERE o.status = 'paid'\nORDER BY o.created_at DESC\nLIMIT 100;`;
const state={view:'query',result:'grid',sql:defaultSql,object:'orders',pinned:false,pinnedObjects:[],dirty:false,ai:false,aiApproved:false,treeState:'ready',resultState:'ready',treeQuery:'',step:1,job:'idle',planView:'graph',variant:'balanced',previewLocked:false,exportScope:'all',importTarget:'orders',engineTab:'primary'};
const titles={query:['SQL 工作区','对象、查询、结果、分析与数据任务连续操作'],table:['对象预览','轻量预览 → 固定标签 → 查看结构 / 编辑 / 导出'],plan:['查询分析','计划节点与源 SQL 对照，未知指标不编造'],import:['数据导入','来源与目标 → 字段映射 → 预检 → 执行'],export:['数据导出','明确当前页、选中行与完整结果集'],jobs:['数据任务','进度、取消回执与结果核验；不是全局调度器'],mongo:['MongoDB 工作区','集合、文档、索引与 Extended JSON'],redis:['Redis 工作区','按数据类型工作，不强套 SQL 表格'],elastic:['Elasticsearch 工作区','文档、索引、Mapping 与版本并发控制'],duck:['DuckDB 文件工作区','登记文件 → 检查格式 → 查询 / 导入'],ai:['SQL 工作区','沿用现有 AI 面板，补齐数据库预览与执行核验']};
const specimenRows=[['9007199254740993','示例用户 A','12.00','{"source":"示例"}',null],['9007199254740994','示例用户 B','20.00','{"tags":["demo"]}',''],['9007199254740995','示例用户 C','0.00','{}','备注示例']];
const columns=[['id','BIGINT · 精确值'],['name','TEXT'],['amount','NUMERIC(18,2)'],['payload','JSON'],['note','TEXT · nullable']];
let toastTimer,queryTimer,jobTimer;
function notice(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3000)}
function fillIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon,el.classList.contains('tb-iconbtn')?17:15))}
function pinnedTabs(){return state.pinnedObjects.filter(name=>name!==state.object).map(name=>`<button class="p-doc-tab" data-pinned-object="${esc(name)}">${icon('table-2')}${esc(name)}${icon('bookmark',12)}</button>`).join('')}
function docTabs(){return `<nav class="p-doc-tabs" aria-label="数据库内部标签"><button class="p-doc-tab ${['query','ai'].includes(state.view)?'active':''}" data-view="query">${icon('file-code')}查询 1<span class="p-badge">未保存</span></button><button class="p-doc-tab ${state.view==='table'?'active':''} ${state.pinned?'':'preview'}" data-view="table">${icon('table-2')}${esc(state.object)}${state.pinned?icon('bookmark',12):'<span class="p-badge">预览</span>'}</button>${pinnedTabs()}${state.view==='plan'?'<span class="p-doc-tab active">'+icon('git-branch')+'查询分析</span>':''}${['import','export','jobs'].includes(state.view)?'<span class="p-doc-tab active">'+icon(state.view==='jobs'?'activity':state.view==='import'?'upload':'download')+esc(titles[state.view][0])+'</span>':''}<span class="p-grow"></span>${state.view==='table'?button(state.pinned?'已固定':'固定预览','pin','bookmark','small'):''}</nav>`}
function targetBar(){return `<div class="p-targetbar"><span>${icon('database',13)} 示例连接</span><span class="p-quiet">/</span><select aria-label="当前默认 Schema"><option>public</option><option>app</option></select><span class="p-badge">权限：读取后确认</span><span class="p-grow"></span><span class="p-badge">会话状态 · 示意</span><button class="p-button small ghost" data-act="transaction">事务操作 ${icon('chevron-down',12)}</button><span class="p-wide-hint p-quiet">实际状态从物理会话读取</span></div>`}
function renderTree(){
  const node=(name,kind='table-2')=>`<button class="p-tree-line ${state.object===name?'active':''}" data-object="${esc(name)}" aria-label="预览 ${esc(name)}">${icon(kind)}<span>${esc(name)}</span><small>⋯</small></button>`;
  const head=(name,fold='')=>`<button class="p-tree-line" data-act="tree-fold" data-fold="${fold}">${icon('chevron-down',12)}${icon('folder',13)}${name}</button>`;
  let content='';
  if(state.treeState==='loading')content='<div class="p-statebox">正在读取对象目录…<br><small>未加载不等于空 schema</small></div>';
  else if(state.treeState==='error')content='<div class="p-statebox error">对象目录读取失败（状态示意）<br><small>保留已有目录，不伪装为空库</small><br>'+button('重试读取','tree-retry','refresh-cw','small')+'</div>';
  else if(state.treeState==='empty')content='<div class="p-statebox">读取成功，此命名空间为空（状态示意）<br><small>仅完整成功后展示空状态</small></div>';
  else if(state.view==='mongo')content=head('示例数据库')+head('集合')+node('orders','braces')+node('users','braces')+'<div class="p-tree-meta">集合 → 文档 / 索引<br>不在缺少集合元数据时猜字段</div>';
  else if(state.view==='redis')content=head('db0 · 示例')+head('键 / 数据类型')+node('events:orders','list')+node('cache:profile','code')+node('queue:pending','list')+'<div class="p-tree-meta">String / Hash / List / Set / ZSet / Stream / JSON<br>大 key 显示已加载字节与上限</div>';
  else if(state.view==='elastic')content=head('索引 · 示例')+node('orders-index','table-2')+head('Alias / Template')+'<div class="p-tree-meta">文档、Mapping、Settings 分开管理</div>';
  else if(state.view==='duck')content=head('当前连接')+node('orders')+head('已登记文件')+node('sample.parquet','file-code')+'<div class="p-tree-meta">仅登记 / 授权文件<br>不接受任意服务器路径</div>';
  else content=`<button class="p-tree-line">${icon('chevron-down',12)}${icon('database',13)}<strong>public</strong><small>默认</small></button>${head('表','tables')}<div data-tree-section="tables">${['orders','users','order_items'].filter(n=>n.includes(state.treeQuery.toLowerCase())).map(n=>node(n)).join('')}</div><div class="p-tree-meta">orders → 字段 / 索引 / 约束<br>按需加载；类型与复合列序保真</div>${head('视图','views')}<div data-tree-section="views">${node('v_orders_summary','eye')}</div>${head('函数 / 程序','functions')}<div data-tree-section="functions">${node('order_total','function-square')}</div><button class="p-tree-line">${icon('chevron-right',12)}${icon('database',13)}app<small>未展开</small></button><div class="p-tree-meta">搜索跨未展开 namespace<br>结果保留 schema / 对象类型</div>`;
  $('#tree-content').innerHTML=content;
}
function gridMarkup(filtered=specimenRows){return `<table class="p-grid"><thead><tr><th>#</th>${columns.map(([n,t])=>`<th>${n}<small>${t}</small></th>`).join('')}</tr></thead><tbody>${filtered.map((row,i)=>`<tr><td class="p-quiet">${i+1}</td>${row.map((v,j)=>`<td data-cell="${specimenRows.indexOf(row)}:${j}" tabindex="0" title="点击查看完整值 / 类型">${v===null?'<span class="p-null">NULL</span>':v===''?'<span class="p-null">空字符串</span>':esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function resultContents(){
  if(state.resultState==='loading')return `<div class="p-empty">${icon('loader',25)}<h3>正在读取…（状态示意）</h3><p>区分等待、取消请求与取消回执；不会用迟到结果覆盖新目标。</p>${button('请求取消','query-cancel','square')}</div>`;
  if(state.resultState==='error')return `<div class="p-empty">${icon('alert-triangle',25)}<h3>查询失败（状态示意）</h3><p>这里展示可操作错误、语句位置和回执。保留 SQL，不自动重放写请求。</p>${button('返回编辑器','error-focus','code')}</div>`;
  if(state.resultState==='empty')return '<div class="p-empty">'+icon('table-2',25)+'<h3>读取成功，结果为空</h3><p>与加载失败、截断、未读取明确区分。</p></div>';
  if(state.result==='messages')return '<div class="p-scrollpage"><div class="p-statebox">示例结果展示。没有真实查询执行、耗时或影响行数回执。</div><p>正式实现：逐语句显示范围、执行 ID、耗时、错误位置和已确认状态。</p></div>';
  if(state.result==='plan')return planMarkup();
  if(state.result==='json')return '<div class="p-scrollpage"><pre class="p-json">'+esc(JSON.stringify({demo:true,columns:columns.map(c=>c[0]),rows:specimenRows},null,2))+'</pre></div>';
  return `<div class="p-result-tools"><input id="result-filter" placeholder="筛选示例结果…" aria-label="筛选结果"><span class="p-badge">结果集 1 · 示例</span><span class="p-grow"></span>${button('完整值','inspect','eye','small')}${viewButton('导出','export','download')}${button('更多','result-more','more-horizontal','small')}</div><div class="p-grid-wrap" id="grid-wrap">${gridMarkup()}</div><div class="p-grid-foot"><span>3 条示例；完整结果数量待真实查询确认</span><span class="p-grow"></span><button class="p-button small" disabled>上一页</button><span>示例页</span><button class="p-button small" disabled>下一页</button></div>`;
}
function resultRegion(){return `<div class="p-results"><div class="p-result-nav" role="tablist" aria-label="查询输出">${[['grid','结果表格'],['json','JSON'],['plan','执行计划'],['messages','消息']].map(([id,label])=>`<button role="tab" aria-selected="${state.result===id}" class="${state.result===id?'active':''}" data-result="${id}">${label}</button>`).join('')}<span class="p-grow"></span><small>设计示意，非执行回执</small></div><div class="p-result-body" id="result-body">${resultContents()}</div></div>`}
function queryMarkup(){return docTabs()+targetBar()+`<div class="p-editor-stack"><div class="p-toolbar">${button('运行当前语句','run','play','primary')}${button('运行选中','run-selection','snippet','',true)}${button('分析','analyze','git-branch')}<span class="p-divider"></span>${button('格式化','format','wrench')}${button('保存','save-query','save')}<span class="p-grow"></span>${button('智能提示','hint','sparkles')}${button('更多','editor-more','more-horizontal')}</div><div class="p-editor"><div class="p-lines" id="line-numbers">${state.sql.split('\n').map((_,i)=>i+1).join('<br>')}</div><textarea class="p-sql" id="sql-input" aria-label="SQL 编辑区（设计示例，不执行）" spellcheck="false">${esc(state.sql)}</textarea></div><div class="p-editor-foot"><span>SQL · 原型编辑示意；正式实现继续使用 CodeMirror</span><span>Alt Enter · 运行 / Ctrl Space · 补全</span></div></div><div class="p-split" id="splitter" role="separator" tabindex="0" aria-label="调整编辑器和结果区比例" aria-orientation="horizontal"></div>`+resultRegion()}
function tableMarkup(){return docTabs()+`<div class="p-targetbar">${icon('table-2',13)}<span class="p-mono">public.${esc(state.object)}</span><span class="p-badge">预览 / 固定共享同一对象身份</span><span class="p-grow"></span>${button('生成 SELECT','generate-select','code','small')}${button('更多','object-more','more-horizontal','small')}</div><div class="p-tabset">${['数据','结构','索引 / 约束','DDL'].map((label,i)=>`<button class="${state.engineTab===String(i)||state.engineTab==='primary'&&i===0?'active':''}" data-table-tab="${i}">${label}</button>`).join('')}</div>${tableContent()}`}
function metadataMarkup(tab){
  const fieldRows=[['id','BIGINT','否','PK','未知','精确身份示例'],['tenant_id','BIGINT','否','FK 1/2','未知','租户边界示例'],['user_id','BIGINT','否','FK 2/2','未知','目标身份示例'],['amount','NUMERIC(18,2)','是','—','未知','保留精度'],['payload','JSON','是','—','未知','完整类型预览'],['note','TEXT','是','—','未知','空字符串与 NULL 分离']];
  const keys=tab==='2'?['约束名称 / 身份','来源列（有序）','目标对象','目标列（有序）']:['字段','类型','可空','键 / 列序','默认值','注释'];
  const rows=tab==='2'?[['fk_orders_user（示例）','tenant_id, user_id','public.users','tenant_id, id'],['pk_orders（示例）','id','—','—']]:fieldRows;
  return '<table class="p-grid"><thead><tr>'+keys.map(k=>'<th>'+k+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
}
function tableContent(){
  if(['1','2','3'].includes(state.engineTab)) {
    const title=state.engineTab==='1'?'字段与类型':state.engineTab==='2'?'完整约束身份':'只读 DDL / 对象源码';
    return `<div class="p-scrollpage"><div class="p-pagehead"><div><h2>${title}</h2><p>显示真实元数据；未知属性标注未知，不用示例结构冒充实际对象。</p></div><span class="p-grow"></span>${button('编辑结构','structure-edit','pencil')}</div>${state.engineTab==='3'?'<pre class="p-codebox">-- DDL 在正式实现中从当前连接读取\n-- 此处不生成或执行未经验证的对象定义</pre>':`<div class="p-section"><div class="p-section-title">${icon('table-2')}元数据排版示意</div>${metadataMarkup(state.engineTab)}</div><div class="p-notice">正式字段表将使用 name / type / nullable / default / key / comment；示例仅供布局评审。</div>`}</div>`;
  }
  return `<div class="p-toolbar">${button('筛选条件','filter-builder','filter')}${button('刷新','table-refresh','refresh-cw')}${button('新增行','row-new','plus')}<span class="p-grow"></span>${viewButton('导入','import','upload')}${viewButton('导出','export','download')}${button('迁移 / 对比','data-tools','git-compare')}</div><div class="p-notice">可读与可编辑分开：表编辑需要稳定行身份、权限与并发检查；任意查询结果不默认可写。</div><div class="p-result-body">${resultContents()}</div>${state.dirty?`<div class="p-draftbar">${icon('pencil')}1 项本地示例草稿 · 尚未写入<span class="p-grow"></span>${button('查看更改','diff','eye','small')}${button('撤销','undo','history','small')}${button('预览并提交','diff','check','primary small')}</div>`:''}`;
}
function planMarkup(){return `<div class="p-scrollpage"><div class="p-pagehead"><div><h2>执行计划与源 SQL</h2><p>计划树、节点详情、原始结果保持关联；不会把估算值叫实测。</p></div><span class="p-grow"></span>${button('AI 解释计划','ai-plan','wand')}</div><div class="p-tabset">${[['graph','节点图'],['tree','计划树'],['raw','原始数据']].map(([id,label])=>`<button class="${state.planView===id?'active':''}" data-plan-view="${id}">${label}</button>`).join('')}</div><div class="p-notice amber">示例结构，不是真实执行计划。默认非执行式 EXPLAIN；ANALYZE 必须另行确认。</div>${state.resultState==='incomplete'?'<div class="p-statebox error">计划不完整（状态示意）：部分节点 / 指标缺失。保留原始结果，不推断完整结论。</div>':''}${state.planView==='raw'?'<pre class="p-codebox">'+esc(JSON.stringify({demo:true,source:'design placeholder',cost:null,actualRows:null,nodes:['Join','Scan','Lookup']},null,2))+'</pre>':`<div class="p-twocol" style="margin-top:17px"><div><button class="p-plan-node selected" data-act="plan-node"><h4>Join · 关联节点示意</h4><p>public.orders → public.users</p><small>代价 / 估算行数：等待驱动返回</small></button><div class="p-plan-node child"><h4>Scan · 来源读取</h4><p>过滤条件与原 SQL 对照</p></div><div class="p-plan-node child"><h4>Lookup · 关联目标</h4><p>完整 FK 配对，不丢失 tenant_id</p></div></div><div class="p-section"><div class="p-section-title">节点详情与分析依据</div><div class="p-section-content"><dl><dt>关联谓词</dt><dd class="p-mono">tenant_id + user_id → tenant_id + id</dd></dl><p>未知的成本、行数、索引命中均留空。建议带依据，不能把模型建议视为数据库事实。</p><small>点击节点联动定位源 SQL（拟实现）</small></div></div></div>`}</div>`}
function stepsMarkup(){return `<div class="p-steps">${['来源与目标','字段映射','预检','执行 / 核验'].map((label,i)=>`<div class="p-step ${state.step===i+1?'active':''}"><em>${i+1}</em>${label}</div>`).join(icon('chevron-right',12))}</div>`}
function importMarkup(){let page='';
  if(state.step===1)page=`<div class="p-form-grid"><label>目标连接<input value="示例连接（未连接）" readonly></label><label>目标表<input value="public.${esc(state.importTarget)}（示例）" readonly></label><label>格式<select><option>CSV</option><option>XLSX</option><option>JSON / typed JSON</option><option>SQL 脚本（独立执行策略）</option></select></label><label>编码<select><option>UTF-8</option><option>GB18030</option></select></label></div><div class="p-upload">${icon('upload',24)}<h3 style="margin:9px 0;font-size:13px">文件选择与流式预览</h3><p>本原型只用示例文件，不读取 / 上传本地数据。</p>${button('使用示例 CSV','sample-file','file-code')}<p id="sample-file-info">尚未选择 · 不接受任意服务器路径</p></div>`;
  else if(state.step===2)page=`<div class="p-section"><div class="p-section-title">来源字段 → 目标字段 → 类型策略</div><table class="p-grid"><thead><tr><th>#</th><th>来源列</th><th>目标列</th><th>目标类型</th><th>规则</th></tr></thead><tbody><tr><td>1</td><td>order_id</td><td><select aria-label="order_id 字段映射"><option>id</option><option>忽略</option></select></td><td>BIGINT</td><td>精确整数</td></tr><tr><td>2</td><td>amount</td><td><select aria-label="amount 字段映射"><option>amount</option><option>忽略</option></select></td><td>NUMERIC(18,2)</td><td>不转浮点数</td></tr><tr><td>3</td><td>note</td><td><select aria-label="note 字段映射"><option>note</option><option>忽略</option></select></td><td>TEXT</td><td>空字符串 ≠ NULL</td></tr></tbody></table></div><div class="p-notice amber">样本字段仅作布局示意。实际映射须读取目标类型、必填字段、生成列及权限。</div>`;
  else if(state.step===3)page=`<div class="p-facts"><div class="p-fact"><small>来源</small><strong>示例 CSV</strong></div><div class="p-fact"><small>目标</small><strong>public.${esc(state.importTarget)}（示例）</strong></div><div class="p-fact"><small>预计影响</small><strong>实际预检后确认</strong></div></div><div class="p-section"><div class="p-section-title">预检项目，不以样本通过代替全文件有效</div><div class="p-section-content"><p>${icon('check',13)} 字段映射、必填列、类型和精度</p><p>${icon('check',13)} 完整输入验证、重复键、空值与二进制保真</p><p>${icon('check',13)} 目标权限、写入策略、事务 / DDL 实际能力</p><p>${icon('info',13)} 结果未知时停止重放，先读取任务回执核验</p></div></div>`;
  else page=`<div class="p-section"><div class="p-section-title">执行与取消状态示意</div><div class="p-section-content"><div class="p-facts"><div class="p-fact"><small>状态</small><strong>${state.job==='cancelled'?'示例：取消回执已收到':state.job==='running'?'示例：处理中':'尚未开始（设计示意）'}</strong></div><div class="p-fact"><small>写入 / 回滚</small><strong>仅以真实执行回执为准</strong></div></div><div class="p-progress"><span style="width:${state.job==='running'?'45':'0'}%"></span></div><p>真实数据任务有执行 ID、资源清理和所有权边界；关闭页面不等于取消成功。</p>${state.job==='running'?button('请求取消（演示）','job-cancel','square','danger'):button('模拟执行状态','job-run','play','primary')}${viewButton('查看任务列表','jobs','activity')}</div></div>`;
  return docTabs()+`<div class="p-scrollpage"><div class="p-pagehead"><div><h2>导入到 public.${esc(state.importTarget)}</h2><p>将分散的图标 / 弹窗组织成连续流程；不会凭一个按钮假装流式后端已完成。</p></div><span class="p-grow"></span><span class="p-badge amber">全部为设计示意</span></div>${stepsMarkup()}${page}</div><div class="p-bottomactions"><small>设计预览；没有文件读取或数据库写入</small><span class="p-grow"></span>${button('上一步','import-back','arrow-left','',state.step===1)}${button(state.step===3?'确认示意并进入执行页':'下一步','import-next','arrow-right','primary',state.step===4)}</div>`;
}
function exportMarkup(){return docTabs()+`<div class="p-scrollpage"><div class="p-pagehead"><div><h2>导出什么，应当一眼明确</h2><p>把导出范围、快照与类型策略放在确认前，不在下载后才发现只导出了当前页。</p></div><span class="p-grow"></span><span class="p-badge amber">设计示意</span></div><div class="p-section"><div class="p-section-title">1 · 范围</div><div class="p-section-content"><div class="p-tabset">${[['page','当前已加载页'],['selected','选中行'],['all','完整查询结果 / 表']].map(([id,label])=>`<button class="${state.exportScope===id?'active':''}" data-export-scope="${id}">${label}</button>`).join('')}</div><p>${state.exportScope==='all'?'完整范围需要后端流式游标 / 快照与执行计划支持，不能拿已加载网格行数冒充完整导出。':state.exportScope==='page'?'明确只导出当前加载页；不暗示整表。':'没有选中行时禁用确认；选中身份必须稳定。'}</p></div></div><div class="p-form-grid"><label>格式<select><option>typed JSON · 无歧义保真</option><option>CSV · 通用交换</option><option>XLSX · 人工分析</option><option>SQL · 恢复脚本</option></select></label><label>一致性<select><option>驱动支持的快照 / 事务</option><option>允许非快照，明确风险</option></select></label></div><div class="p-section" style="margin-top:16px"><div class="p-section-title">2 · 类型与预览</div><div class="p-section-content"><p>精确整数 / 小数、NULL / 空串 / 空字节、BLOB / 同形 hex 文本不混淆。复杂类型与完整 DDL 必须逐引擎验证。</p><pre class="p-codebox"># 设计说明：实际格式由后端协议定义\n范围: ${esc(state.exportScope)}\n目标: 浏览器下载 或 Tauri 保存对话框\n进度: 执行 ID + 已确认读取量 + 取消回执</pre></div></div></div><div class="p-bottomactions"><span class="p-quiet">原型不生成文件，不触发真实导出</span><span class="p-grow"></span>${button('模拟创建导出任务','export-task','download','primary',state.exportScope==='selected')}</div>`}
function jobsMarkup(){return docTabs()+`<div class="p-scrollpage"><div class="p-pagehead"><div><h2>数据任务</h2><p>数据库内部任务入口；不是改造 MCP、SFTP 或增加新的全局任务系统。</p></div><span class="p-grow"></span>${viewButton('新建导入','import','upload')}</div><div class="p-section"><table class="p-grid"><thead><tr><th>#</th><th>任务 / 类型</th><th>目标</th><th>状态</th><th>操作</th></tr></thead><tbody><tr><td>1</td><td>示例导入 · CSV</td><td>public.orders</td><td>${state.job==='running'?'处理中（示意）':state.job==='cancelled'?'取消回执（示意）':'未开始（示意）'}</td><td>${state.job==='running'?button('请求取消','job-cancel','square','small danger'):button('状态演示','job-run','play','small')}</td></tr><tr><td>2</td><td>未知结果场景</td><td>未确认目标</td><td><span class="p-badge amber">需核验（示意）</span></td><td>${button('核验回执','verify-receipt','shield','small')} ${button('直接重试','blocked-retry','','small',true)}</td></tr></tbody></table></div><div class="p-section"><div class="p-section-title">状态契约</div><div class="p-section-content"><p>准备 → 全输入预检 → 等待确认 → 运行 → 取消请求 → 已取消 / 部分已确认 / 结果未知 / 成功</p><p>只有存在真实回执，才标成功或回滚。未知结果必须先核验，不能直接重试写入。</p><small>“恢复”仅对已实现幂等检查点的任务开放；不能笼统承诺所有数据库可恢复。</small></div></div></div>`}
function specializedMarkup(){
  const toolbar=`<div class="p-toolbar">${button('刷新','special-refresh','refresh-cw')}${button('预览变更','diff','eye')}<span class="p-grow"></span>${viewButton('导入','import','upload')}${viewButton('导出','export','download')}${button('AI 辅助','ai-toggle','wand')}</div>`;
  if(state.view==='mongo')return `<div class="p-doc-tabs"><span class="p-doc-tab active">${icon('braces')}orders · 集合示例</span></div>${toolbar}<div class="p-tabset"><button class="active">文档</button><button data-act="mongo-index">索引</button><button data-act="mongo-filter">过滤器 / 排序</button></div><div class="p-scrollpage"><div class="p-pagehead"><div><h2>文档，而不是压扁成一张 SQL 表</h2><p>Grid / Tree / Extended JSON 可切换。原始类型、精确主键与并发版本必须保留。</p></div></div><pre class="p-codebox p-json">${esc(JSON.stringify({_id:{$oid:'000000000000000000000001'},amount:{$numberDecimal:'12.00'},created_at:{$date:{$numberLong:'0'}},note:null},null,2))}</pre><div class="p-notice amber">示例文档，不是实际数据库数据。不能把同形字符串 / 类型包装对象推断成 ObjectId；定位和写入需保真身份协议。</div><div class="p-toolbar">${button('编辑文档（演示）','mongo-edit','pencil')}${button('复制 Extended JSON','copy-json','copy')}</div></div>`;
  if(state.view==='redis')return `<div class="p-doc-tabs"><span class="p-doc-tab active">${icon('list')}events:orders · Stream 示例</span></div><div class="p-targetbar"><span>类型：Stream</span><span class="p-badge">TTL / 总长度：读取后展示</span><span class="p-grow"></span>${button('TTL 设置','redis-ttl','clock','small')}</div>${toolbar}<div class="p-tabset"><button class="active">消息</button><button data-act="stream-groups">消费者组</button><button data-act="stream-pending">Pending</button></div><div class="p-scrollpage"><div class="p-section"><table class="p-grid"><thead><tr><th>#</th><th>消息 ID</th><th>Fields（示例）</th><th>操作</th></tr></thead><tbody><tr><td>1</td><td>0-1</td><td>{order_id: "demo-1", event: "created"}</td><td>${button('完整值','inspect-stream','eye','small')}</td></tr></tbody></table></div><div class="p-section"><div class="p-section-title">按类型提供操作</div><div class="p-section-content"><p>String / Hash / List / Set / ZSet / Stream / JSON 分开显示。键名、消息 ID、二进制值不依赖显示文本猜测身份。</p><p>大 key 有界读取，显示已加载量 / 总量是否未知。批量操作显式列出选中的键，不用宽泛 pattern 暗中扩大范围。</p></div></div></div>`;
  if(state.view==='elastic')return `<div class="p-doc-tabs"><span class="p-doc-tab active">${icon('table-2')}orders-index · 索引示例</span></div>${toolbar}<div class="p-tabset"><button class="active">文档</button><button data-act="es-mapping">Mapping</button><button data-act="es-settings">Settings</button><button data-act="es-alias">Alias</button></div><div class="p-scrollpage"><div class="p-form-grid"><label class="wide">Query DSL<textarea style="height:115px;padding:10px" aria-label="Elasticsearch Query DSL 示例">${esc('{\n  "query": { "match_all": {} },\n  "size": 100\n}')}</textarea></label></div><div class="p-toolbar">${button('查询示例','special-refresh','play','primary')}${button('文档编辑','es-edit','pencil')}</div><div class="p-section"><div class="p-section-title">文档定位与版本保护</div><div class="p-section-content"><p>_id / _seq_no / _primary_term 与正文分离，保存前核验版本冲突；Mapping / 索引管理的权限与风险独立确认。</p><small>本原型不调用集群接口，也不表示 ES 管理能力已经交付。</small></div></div></div>`;
  return `<div class="p-doc-tabs"><span class="p-doc-tab active">${icon('file-code')}sample.parquet · 文件示例</span></div>${toolbar}<div class="p-scrollpage"><div class="p-pagehead"><div><h2>文件即查询对象，但不是任意服务器路径</h2><p>CSV / JSON / Parquet 的登记、结构预览、查询与落表使用一条连续路径。</p></div></div><div class="p-section"><div class="p-section-title">登记文件与 schema 预览</div><div class="p-section-content"><div class="p-facts"><div class="p-fact"><small>文件</small><strong>sample.parquet（示例）</strong></div><div class="p-fact"><small>权限</small><strong>仅登记文件 / 授权目录</strong></div></div><p>浏览器上传令牌或 Tauri 文件选择；带所有权与生命周期。禁止用户输入任意后端文件路径。</p>${button('文件登记说明','duck-register','file-code')}${button('生成查询','duck-query','code')}${button('预览导入为表','duck-import','upload')}</div></div><div class="p-notice">自动推断只提供预览；实际导入仍需确认类型、覆盖策略及一致性。</div></div>`;
}
function renderAI(){
  $('#ai-panel').hidden=!state.ai;document.body.classList.toggle('p-ai-open',state.ai);
  if(!state.ai)return;
  $('#ai-panel').innerHTML=`<div class="p-ai-head">${icon('wand')}<strong>数据库 AI</strong><span class="p-grow"></span><button class="p-icon-button" data-act="ai-toggle" aria-label="关闭 AI 面板">${icon('x')}</button></div><div class="p-ai-body"><span class="p-badge amber">示例建议 · 非模型调用</span><div class="p-ai-context"><strong>本轮上下文（设计示意）</strong><p>示例连接 / public / 当前查询</p><span class="p-badge">orders</span> <span class="p-badge">users</span><p>只发送必要结构；失败时不发送，不默认上传整库，不包含连接 secret。</p></div><div class="p-ai-stage"><strong>1 · 建议与依据</strong><p>示例：按完整主键限定更新，并在写入前预览目标、权限与影响范围。</p><pre class="p-codebox">UPDATE public.orders\nSET amount = 13.00\nWHERE tenant_id = 1\n  AND id = 9007199254740993;</pre></div><div class="p-ai-stage"><strong>2 · 应用侧确认</strong><small>模型建议不是授权；提示词不代替工具权限。</small>${button('预览影响与 SQL 差异','ai-preview','eye','small')}${button('模拟审批','ai-approve','shield','small primary')}</div><div class="p-ai-stage"><strong>3 · 回执与读回</strong><div class="p-receipt">${state.aiApproved?'已展示模拟确认状态。未向任何数据库发请求；没有真实成功 / 回滚回执。':'未批准；未执行。正式实现须显示执行 ID、受影响范围和读回证据。'}</div></div></div><div class="p-ai-bottom"><textarea placeholder="解释 SQL、分析计划或提出维护目标…" aria-label="AI 输入示意"></textarea><small>评审稿不调用 DeepSeek 或其他模型</small></div>`;
}
function render(){
  const title=titles[state.view]||titles.query;$('#db-title').textContent=title[0];$('#db-subtitle').textContent=title[1];$('#review-scene').value=state.view;
  $('#vault-label').textContent=['mongo','redis','elastic','duck'].includes(state.view)?title[0].replace('工作区','· 示例'):'数据库 · 示例';
  renderTree();
  const html=state.view==='table'?tableMarkup():state.view==='plan'?docTabs()+planMarkup():state.view==='import'?importMarkup():state.view==='export'?exportMarkup():state.view==='jobs'?jobsMarkup():['mongo','redis','elastic','duck'].includes(state.view)?specializedMarkup():queryMarkup();
  $('#canvas').innerHTML=html;renderAI();fillIcons();wireSplitter();
}
function changeView(view){
  clearTimeout(queryTimer);state.resultState='ready';state.engineTab='primary';state.view=view;
  if(view==='import'){state.step=1;state.importTarget=state.object;}if(view==='ai')state.ai=true;render();
}
function showDialog(title,html,footer=''){const overlay=$('#overlay');overlay.innerHTML=`<section class="p-dialog" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="p-dialog-head"><h2>${esc(title)}</h2><span class="p-grow"></span><button class="p-icon-button" data-act="close-dialog" aria-label="关闭对话框">${icon('x')}</button></div><div class="p-dialog-body">${html}</div>${footer?'<div class="p-bottomactions">'+footer+'</div>':''}</section>`;overlay.hidden=false;overlay.querySelector('button')?.focus()}
function closeDialog(){const root=$('#overlay');root.hidden=true;root.innerHTML=''}
function showMenu(kind,at){
  let groups;
  if(kind==='editor')groups=[['运行', [['运行当前 / 选中 SQL','run','play','Alt ↵'],['预览写入影响','diff','eye'],['分析当前语句','analyze','git-branch']]],['编辑与上下文',[['格式化','format','wrench'],['生成完整 JOIN 条件','hint','sparkles','Ctrl Space'],['查看引用对象','object-more','table-2'],['发送选中内容给 AI','ai-toggle','wand']]],['文件与数据',[['保存查询','save-query','save'],['运行 SQL 文件','sql-file','file-code'],['导出查询结果','to-export','download']]]];
  else if(kind==='result')groups=[['选中内容',[['完整值 / 类型','inspect','eye'],['复制值','copy-value','copy','Ctrl C'],['列显示 / 排序','grid-columns','columns']]],['结果范围',[['导出当前页','export-page','download'],['导出完整结果','to-export','download'],['发送选中内容给 AI','ai-toggle','wand']]]];
  else if(kind==='transaction')groups=[['事务（实际能力决定）',[['开始事务','txn-begin','play'],['提交','txn-commit','check'],['回滚','txn-rollback','history']]]];
  else groups=[['浏览 / 预览',[['预览数据','to-table','eye'],['固定预览','pin','bookmark'],['查看字段 / 约束','to-structure','table-2'],['复制限定名称','copy-name','copy']]],['查询 / 数据',[['生成 SELECT','generate-select','code'],['导入数据','to-import','upload'],['导出数据','to-export','download'],['迁移 / 对比','data-tools','git-compare']]],['对象维护（保留现有能力）',[['重命名 / 复制结构','structure-edit','pencil'],['清空表 / 删除对象','danger-object','trash-2']]]];
  const menu=$('#context-menu');menu.innerHTML=groups.map(([label,items])=>`<div class="p-context-group">${label}</div>${items.map(([text,act,name,key])=>`<button role="menuitem" data-act="${act}" class="${act==='danger-object'?'danger':''}">${icon(name,14)}${text}${key?'<kbd>'+key+'</kbd>':''}</button>`).join('')}`).join('<hr>');menu.hidden=false;
  const rect=at?.getBoundingClientRect?.();const x=at?.clientX ?? rect?.left ?? 600;const y=at?.clientY ?? rect?.bottom ?? 250;
  const measured=menu.getBoundingClientRect();menu.style.left=Math.max(6,Math.min(x,innerWidth-measured.width-10))+'px';menu.style.top=Math.max(42,Math.min(y,innerHeight-measured.height-10))+'px';menu.querySelector('button')?.focus();
}
function inspector(row=0,col=3){
  const value=specimenRows[row]?.[col];const host=$('#result-body')||$('#canvas');host.querySelector('.p-inspector')?.remove();
  const panel=document.createElement('aside');panel.className='p-inspector';panel.innerHTML=`<div class="p-inspector-head"><strong>完整值与原始类型</strong><span class="p-grow"></span><button class="p-icon-button" data-act="close-inspector" aria-label="关闭值预览">${icon('x')}</button></div><span class="p-badge amber">示例单元格</span><dl><dt>字段</dt><dd>${esc(columns[col]?.[0])}</dd><dt>原始类型</dt><dd>${esc(columns[col]?.[1])}</dd><dt>值</dt><dd><pre class="p-codebox">${value===null?'NULL（不是字符串）':value===''?'空字符串（不是 NULL）':esc(value)}</pre></dd><dt>编辑权限</dt><dd>以主键身份、capability 和版本核验为准；查询网格不默认可写。</dd></dl>${button('复制完整值','copy-value','copy')}${state.view==='table'?button('编辑草稿（演示）','cell-edit','pencil'):''}`;host.append(panel);
}
function hint(){
  if(!$('.p-editor')){changeView('query')}
  $('.p-hint')?.remove();const panel=document.createElement('div');panel.className='p-hint';panel.innerHTML=`<small>示例补全 · 完整约束与实际作用域（产品实现已有，原型仅演示排版）</small><button data-act="accept-join"><strong>public.users · 复合外键</strong><code>ON o.tenant_id = u.tenant_id AND o.user_id = u.id</code><small>来源对象 / 约束 / 列顺序同时可见</small></button><button data-act="accept-function"><strong>SUBSTR(string, start, length)</strong><small>Tab / Shift Tab 跳转参数占位</small></button>`;$('.p-editor').append(panel)
}
function previewDiff(ai=false){showDialog(ai?'AI 建议：目标 / 权限 / 影响预览':'变更预览：不能隐藏真实目标',`<div class="p-facts"><div class="p-fact"><small>目标</small><strong>示例连接 / public.orders</strong></div><div class="p-fact"><small>执行状态</small><strong>原型，没有数据库请求</strong></div></div><p>真实实现必须检查稳定身份、实际权限、版本冲突及适用事务语义。不能把 SELECT 预览等同完整写入影响保证。</p><pre class="p-codebox">-- 示意差异，不是真实写入\n- amount = 12.00\n+ amount = 13.00\nWHERE tenant_id = 1 AND id = 9007199254740993</pre><div class="p-notice amber">DDL 的依赖、不可回滚行为和影响范围独立确认；未知结果先核验，不直接重试。</div>`,`<span class="p-grow"></span>${button('返回','close-dialog')}${button('模拟确认（不执行）',ai?'confirm-ai':'confirm-draft','shield','primary')}`)}
function review(){showDialog('设计方向：Catio 外框不变，数据库内部重新组织',`<p><strong>推荐：对象导航 + 主工作区 + 按需预览。</strong>不是复制 DBX 外壳，而是沿用 Catio tokens，让数据库流程变得明确。</p><h3>不改造</h3><p>主标题栏、连接保险库、主工作标签、右侧工具栏；主机 SSH / SFTP / 隧道 / MCP 功能与服务不变。AI 只补数据库上下文，宿主模式不变。</p><h3>重点改造与理由</h3><table><tr><th>区域</th><th>新设计</th><th>理由</th></tr><tr><td>SQL 编辑区</td><td>运行范围、分析、格式化等常用操作有文字；次要动作进菜单</td><td>减少猜图标与误跑脚本</td></tr><tr><td>对象树</td><td>类型分组、带 namespace 搜索、单击预览 / 双击固定、完整元数据状态</td><td>减少标签堆积与同名对象混淆</td></tr><tr><td>菜单</td><td>按对象 / 语句 / 结果分组，目标固定、危险操作独立确认</td><td>不依赖失焦后的旧选择，不扩大操作范围</td></tr><tr><td>数据网格</td><td>条件构建器、完整值与类型、草稿更改条、导出范围</td><td>可读和可写分开；避免 NULL / 空串 / 精度丢失</td></tr><tr><td>导入导出</td><td>来源目标 → 映射 → 预检 → 任务 / 核验</td><td>形成连续流程；不用“当前页”冒充完整导出</td></tr><tr><td>专用工作区 / AI</td><td>按数据模型展示；建议 → 预览 → 应用确认 → 回执 / 读回</td><td>不强套 SQL，也不把模型输出当执行授权</td></tr></table><h3>评审稿的诚实边界</h3><p>全部数据、计划、任务和 AI 文本为明示示例；没有 fetch / IPC / 文件读取 / 模型调用。原型按钮能点，不表示后端功能已实现。审批通过后仍按 1 → 6 → 5 → 7 → 8 的顺序交付真实场景。</p><p>按 Tweaks 可对比平衡 / 编辑器主导 / 数据主导三种内部比例，主题、密度、加载 / 空 / 错误 / 不完整状态。正式快捷键必须避开主机与 SFTP。</p>`)}
function command(){showDialog('数据库快捷操作',`<input id="command-search" class="p-command-input" placeholder="输入操作或对象…" aria-label="搜索数据库快捷操作"><div class="p-command-list">${[['新建查询','query','当前数据库上下文，不改变主外框'],['预览对象','table','单击临时预览，固定后保持标签'],['分析查询','plan','非执行式计划，节点与原始信息联动'],['导入数据','import','分步映射、预检、确认'],['导出数据','export','明确范围、类型与一致性'],['查看数据任务','jobs','进度、取消回执、结果未知核验']].map(([text,view,desc])=>`<button data-command-view="${view}" data-search="${text}">${text}<small>${desc}</small></button>`).join('')}</div>`)}
function tweaks(){const p=$('#tweaks');p.hidden=!p.hidden;if(p.hidden)return;p.innerHTML=`<h3>Tweaks · 评审设置<button data-act="tweaks" aria-label="关闭评审设置">${icon('x')}</button></h3><label>内部布局<select id="variant"><option value="balanced">A · 平衡工作台（推荐）</option><option value="editor">B · 编辑器主导</option><option value="data">C · 数据主导</option></select></label><label>现有主题<select id="theme"><option value="dawn">Dawn</option><option value="amber">Amber</option><option value="grove">Grove</option></select></label><label>密度<select id="density"><option value="normal">标准</option><option value="compact">紧凑</option><option value="comfortable">舒适</option></select></label><label>输出状态<select id="result-state"><option value="ready">成功 / 示例</option><option value="loading">加载中</option><option value="empty">成功空结果</option><option value="error">失败</option><option value="incomplete">计划不完整</option></select></label><label>不变区域标注<input id="boundaries" type="checkbox"></label><small>这些控件只属于评审稿，不新增全局产品设置。</small>`;$('#variant').value=state.variant;$('#theme').value=document.documentElement.dataset.theme;$('#result-state').value=state.resultState;$('#boundaries').checked=document.body.classList.contains('p-boundaries')}
function wireSplitter(){const splitter=$('#splitter');if(!splitter)return;splitter.addEventListener('pointerdown',event=>{event.preventDefault();splitter.setPointerCapture(event.pointerId);const root=$('#canvas');const rect=root.getBoundingClientRect();const move=e=>{const p=Math.max(25,Math.min(66,(e.clientY-rect.top)/rect.height*100));document.documentElement.style.setProperty('--p-editor-ratio',p+'%')};const done=()=>{splitter.removeEventListener('pointermove',move);splitter.removeEventListener('pointerup',done);splitter.removeEventListener('pointercancel',done)};splitter.addEventListener('pointermove',move);splitter.addEventListener('pointerup',done);splitter.addEventListener('pointercancel',done)});splitter.addEventListener('keydown',e=>{if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const n=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--p-editor-ratio'))||41;document.documentElement.style.setProperty('--p-editor-ratio',Math.max(25,Math.min(66,n+(e.key==='ArrowUp'?-3:3)))+'%')})}
function act(name,element){
  switch(name){
    case 'review':review();break;case 'tweaks':tweaks();break;case 'close-dialog':closeDialog();break;
    case 'command':command();break;case 'theme':{const list=['dawn','amber','grove'];document.documentElement.dataset.theme=list[(list.indexOf(document.documentElement.dataset.theme)+1)%3];break}
    case 'tree-collapse':$('.p-tree').classList.toggle('collapsed');break;
    case 'tree-fold':{const box=document.querySelector(`[data-tree-section="${element.dataset.fold}"]`);if(box)box.hidden=!box.hidden;break}
    case 'tree-state':state.treeState=['ready','loading','error','empty'][(['ready','loading','error','empty'].indexOf(state.treeState)+1)%4];renderTree();break;
    case 'tree-retry':state.treeState='ready';renderTree();break;
    case 'run':case 'run-selection':if(!['query','ai'].includes(state.view))changeView('query');state.resultState='loading';$('#result-body').innerHTML=resultContents();clearTimeout(queryTimer);queryTimer=setTimeout(()=>{state.resultState='ready';$('#result-body')&&($('#result-body').innerHTML=resultContents());notice('仅展示示例结果；没有执行 SQL，也没有真实耗时回执')},650);break;
    case 'query-cancel':clearTimeout(queryTimer);state.resultState='ready';$('#result-body').innerHTML='<div class="p-empty"><h3>示例取消状态</h3><p>真实实现等待驱动取消回执，不把停止等待说成底层已取消或已回滚。</p></div>';break;
    case 'error-focus':$('#sql-input')?.focus();break;
    case 'analyze':state.result='plan';state.resultState='ready';render();break;
    case 'format':notice('排版与快捷键示意；正式实现继续使用真实方言 formatter');break;
    case 'save-query':notice('拟保留保存 / 历史 / 片段功能；本原型不落盘查询');break;
    case 'hint':hint();break;
    case 'accept-join':state.sql=defaultSql;render();notice('示例完整 JOIN 候选接受；非数据库元数据验证');break;
    case 'accept-function':state.sql="SELECT SUBSTR(string, start, length);";render();const input=$('#sql-input');input.focus();input.setSelectionRange(14,20);notice('占位示意；正式实现使用 CodeMirror snippet 字段');break;
    case 'editor-more':showMenu('editor',element);break;case 'result-more':showMenu('result',element);break;case 'object-more':showMenu('object',element);break;case 'transaction':showMenu('transaction',element);break;
    case 'pin':state.pinned=true;if(!state.pinnedObjects.includes(state.object))state.pinnedObjects.push(state.object);render();notice('示例对象已固定；单击其他对象不覆盖固定标签');break;
    case 'inspect':inspector();break;case 'close-inspector':$('.p-inspector')?.remove();break;
    case 'cell-edit':case 'row-new':case 'mongo-edit':state.dirty=true;state.view='table';render();notice('本地示例草稿；尚未写入任何数据库');break;
    case 'undo':state.dirty=false;render();break;
    case 'diff':previewDiff();break;case 'confirm-draft':state.dirty=false;closeDialog();render();notice('仅模拟确认；没有真实写入、成功或回滚回执');break;
    case 'ai-plan':state.ai=true;renderAI();notice('示例 AI 计划上下文；没有模型调用');break;case 'ai-toggle':state.ai=!state.ai;renderAI();break;
    case 'ai-preview':case 'ai-approve':previewDiff(true);break;case 'confirm-ai':state.aiApproved=true;closeDialog();renderAI();notice('仅模拟审批，未执行数据库操作');break;
    case 'filter-builder':showDialog('结构化筛选：参数绑定与方言转换由后端负责',`<div class="p-form-grid"><label>字段<select><option>status</option><option>amount</option></select></label><label>操作符<select><option>等于</option><option>不等于</option><option>为空</option></select></label><label class="wide">值<input value="paid"></label></div><p>显示生成的条件，但不直接拼接不可信用户值。跨页排序 / 筛选在服务端执行；不能只筛当前页却声称整表。</p>`,button('返回','close-dialog'));break;
    case 'table-refresh':case 'special-refresh':notice('仅刷新示例排版；没有请求真实服务');break;
    case 'grid-columns':showDialog('列与网格操作',`<p>保留已有列宽拖动、横纵滚动、完整值、复制等能力；列显示 / 固定 / 排序逐项实现并独立验收。</p><p>不可用操作附原因，不用菜单开关冒充驱动能力。</p>`);break;
    case 'generate-select':state.sql=`-- 示例生成，未执行\nSELECT id, amount, note\nFROM public.${state.object}\nLIMIT 100;`;changeView('query');notice('示例生成 SELECT；真实实现按 engine / schema 引用名称');break;
    case 'sql-file':showDialog('SQL 文件执行',`<p>保留已有入口，新设计纳入数据任务流程。预览语句范围、方言、编码、错误继续策略、执行 ID 与清理状态。</p><p>完整流式 I/O、真实当前语句取消、Web 文件令牌和恢复检查点尚需实现；不能以修复 splitter 代替这些能力。</p>`);break;
    case 'data-tools':showDialog('迁移 / 对比：源与目标都必须明确',`<div class="p-form-grid"><label>源连接<input value="示例源（未连接）" readonly></label><label>目标连接<input value="示例目标（未连接）" readonly></label></div><p>复用已有类型保真与暂存后替换能力，逐步补全流式一致性和全范围对比。现有 5,000 行对比窗口必须明示，不算全表同步。</p><p>不默认覆盖目标；有稳定键、权限、写入预检和确认才能执行。</p>`);break;
    case 'structure-edit':showDialog('结构编辑：保留原能力，不自动扩张专项',`<p>表字段 / 索引 / 约束展示统一。已有编辑能力按实际驱动保留；新的复杂安全重建、ER 大图、备份等不偷偷并入本轮。</p><p>如需另行扩展，先说明依赖、事务限制和失败路径，再评审。</p>`);break;
    case 'danger-object':showDialog('危险操作：单独确认明确对象',`<p>此处只演示清空 / 删除的交互入口。目标必须绑定本次点击的连接、namespace、对象，不跟随迟到选择。</p><div class="p-notice amber">不能保证 DDL 可回滚；批量操作列出每个目标。没有真实权限信息时禁用确认。</div>`,button('关闭（本原型不可执行）','close-dialog'));break;
    case 'sample-file':$('#sample-file-info').textContent='示例 CSV 已选择（仅状态展示，未读取文件）';break;
    case 'import-next':state.step=Math.min(4,state.step+1);render();break;case 'import-back':state.step=Math.max(1,state.step-1);render();break;
    case 'job-run':state.job='running';render();notice('任务处理中状态示意，未导入任何数据');break;
    case 'job-cancel':state.job='cancelled';render();notice('演示取消回执；真实部分写入 / 回滚结果只能由执行回执证明');break;
    case 'export-task':state.view='jobs';state.job='idle';render();notice('仅展示任务设计；没有生成或下载文件');break;
    case 'verify-receipt':showDialog('结果未知：先核验，不盲目重放',`<p>通过真实执行 ID / 会话状态 / 目标读回判断已确认范围。不能在网络失败时假定已回滚。</p><p>没有足够证据时停留“需人工核验”；恢复仅在幂等检查点完整时可用。</p>`);break;
    case 'to-table':changeView('table');break;case 'to-structure':state.view='table';state.engineTab='1';render();break;case 'to-import':changeView('import');break;case 'to-export':changeView('export');break;case 'export-page':state.exportScope='page';changeView('export');break;
    case 'copy-name':case 'copy-value':case 'copy-json':notice('复制入口与键盘范围示意；本评审稿不更改系统剪贴板');break;
    case 'plan-node':notice('正式实现：节点详情与源 SQL 范围联动，所有结论保留真实依据');break;
    default:showDialog('能力与交互说明',`<p>${esc({ 'mongo-index':'MongoDB 索引单独管理；准确目标与写权限校验。','mongo-filter':'Mongo 查询使用原生数据模型，Extended JSON 类型不退化为普通字符串。','redis-ttl':'TTL / 永不过期分开；键身份与权限需确认。','stream-groups':'消费者组、消费者、Lag / Pending 状态按真实返回展示。','stream-pending':'Pending 读取有游标 / 范围 / 预算；ACK 等写操作单独确认。','inspect-stream':'完整消息 ID / 原始字段与字节类型；不从截断文本恢复身份。','es-mapping':'Mapping 独立展示与管理；修改之前检查版本 / 权限 / 依赖。','es-settings':'索引设置与集群管理不是同一权限范围。','es-alias':'Alias 显示真实指向，变更预览明确所有索引目标。','es-edit':'保存文档使用 _seq_no / _primary_term 并发保护，冲突不自动覆盖。','duck-register':'Web 文件令牌与 Tauri 文件选择都必须验证所有权与生命周期。','duck-query':'仅授权文件的查询对象，不接受模型生成的任意服务器路径。','duck-import':'格式预览 → 字段类型 → 目标 / 覆盖策略 → 导入预检。','txn-begin':'按查询会话真实 capability 开放；不暗中换物理连接。','txn-commit':'只有实际会话可提交；目标变化与结果未知时禁用盲目操作。','txn-rollback':'回滚仅以实际驱动回执为准，不能保证所有 DDL 可回滚。'}[name]||'拟实现交互；此原型没有数据库或模型请求。')}</p>`);
  }
}
function closeMenu(){$('#context-menu').hidden=true}
document.addEventListener('click',event=>{
  const el=event.target.closest('button');
  if(!event.target.closest('#context-menu'))closeMenu();
  if(!el||el.disabled)return;
  if(el.dataset.view){changeView(el.dataset.view);return}
  if(el.dataset.commandView){closeDialog();changeView(el.dataset.commandView);return}
  if(el.dataset.result){state.result=el.dataset.result;state.resultState='ready';render();return}
  if(el.dataset.planView){state.planView=el.dataset.planView;render();return}
  if(el.dataset.exportScope){state.exportScope=el.dataset.exportScope;render();return}
  if(el.dataset.tableTab){state.engineTab=el.dataset.tableTab;render();return}
  if(el.dataset.pinnedObject){state.object=el.dataset.pinnedObject;state.pinned=true;state.view='table';state.engineTab='primary';render();return}
  if(el.dataset.object){if(state.dirty&&state.object!==el.dataset.object){notice('当前对象有草稿，请先查看或撤销；不会静默覆盖');return}state.object=el.dataset.object;state.pinned=state.pinnedObjects.includes(state.object);if(!['mongo','redis','elastic','duck'].includes(state.view))state.view='table';state.result='grid';state.engineTab='primary';render();return}
  if(el.dataset.act){const action=el.dataset.act;closeMenu();act(action,el)}
});
document.addEventListener('dblclick',event=>{const el=event.target.closest('[data-object]');if(el){state.object=el.dataset.object;state.pinned=true;if(!state.pinnedObjects.includes(state.object))state.pinnedObjects.push(state.object);if(!['mongo','redis','elastic','duck'].includes(state.view))changeView('table');else render()}});
document.addEventListener('contextmenu',event=>{
  if(event.target.closest('.p-tree-line[data-object]')){event.preventDefault();state.object=event.target.closest('[data-object]').dataset.object;showMenu('object',event)}
  else if(event.target.closest('.p-sql')){event.preventDefault();showMenu('editor',event)}
  else if(event.target.closest('.p-grid')){event.preventDefault();showMenu('result',event)}
});
document.addEventListener('click',event=>{const cell=event.target.closest('[data-cell]');if(cell){const [r,c]=cell.dataset.cell.split(':').map(Number);inspector(r,c)}});
document.addEventListener('input',event=>{
  if(event.target.id==='sql-input'){state.sql=event.target.value;$('#line-numbers').innerHTML=state.sql.split('\n').map((_,i)=>i+1).join('<br>')}
  if(event.target.id==='tree-search'){state.treeQuery=event.target.value;renderTree()}
  if(event.target.id==='result-filter'){$('#grid-wrap').innerHTML=gridMarkup(specimenRows.filter(row=>row.some(v=>String(v).toLowerCase().includes(event.target.value.toLowerCase()))))}
  if(event.target.id==='command-search')document.querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.includes(event.target.value));
});
document.addEventListener('selectionchange',()=>{const input=$('#sql-input');const runSelected=$('[data-act="run-selection"]');if(input&&runSelected)runSelected.disabled=input.selectionStart===input.selectionEnd});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.id==='review-scene')changeView(el.value);
  if(el.id==='theme')document.documentElement.dataset.theme=el.value;
  if(el.id==='density')document.documentElement.style.setProperty('--p-row-height',{normal:'36px',compact:'29px',comfortable:'44px'}[el.value]);
  if(el.id==='boundaries')document.body.classList.toggle('p-boundaries',el.checked);
  if(el.id==='result-state'){state.resultState=el.value;render()}
  if(el.id==='variant'){state.variant=el.value;document.documentElement.style.setProperty('--p-editor-ratio',{balanced:'41%',editor:'62%',data:'28%'}[el.value]);document.documentElement.style.setProperty('--p-tree-width',el.value==='editor'?'184px':'216px')}
});
document.addEventListener('keydown',event=>{
  if(event.isComposing)return;
  if(event.key==='Escape'){closeMenu();closeDialog();$('.p-hint')?.remove();$('#tweaks').hidden=true;return}
  if(event.ctrlKey&&event.shiftKey&&event.key.toLowerCase()==='p'){event.preventDefault();command()}
  if(event.target.id==='sql-input'&&event.ctrlKey&&event.code==='Space'){event.preventDefault();hint()}
  if(event.target.id==='sql-input'&&event.altKey&&event.key==='Enter'){event.preventDefault();act('run')}
  if(event.target.id==='sql-input'&&event.key==='Tab'&&state.sql.startsWith('SELECT SUBSTR(string')){event.preventDefault();const fields=[[14,20],[22,27],[29,35]];const i=fields.findIndex(([a,b])=>event.target.selectionStart===a&&event.target.selectionEnd===b);const next=Math.max(0,Math.min(2,i+(event.shiftKey?-1:1)));event.target.setSelectionRange(...fields[next])}
});
$('#overlay').addEventListener('click',event=>{if(event.target===$('#overlay'))closeDialog()});
fillIcons();render();
})();
